class ToastrService{constructor($mdToast){this.$mdToast=$mdToast}showErrorToast(errorMessage){const defaultMessage="An unexpected error occurred. Please try again";if(!errorMessage){errorMessage=defaultMessage}console.log("Error:",errorMessage);this.showToast(defaultMessage,"error")}showSuccessToast(successMessage){console.log("Success:",successMessage);this.showToast(successMessage,"success")}showWarningToast(warningMessage){console.log("Warning:",warningMessage);this.showToast(warningMessage,"warning")}showToast(message,theme){this.$mdToast.show(this.$mdToast.simple().textContent(message).position("top right").hideDelay(1e4).theme(theme+"-toast"))}}angular.module("uDispatch").service("toastrService",ToastrService);